inputConversions.prepareProcedure:
async(f)=>{
  const group=f[0].includes('--alb')?'alb':f[0].includes('--nlb')?'nlb':'clb';
  for(const [g,name]of [['alb','Application Load Balancer'],['nlb','Network Load Balancer'],['clb','Classic Load Balancer']]){await inputLocal('input-profile--'+g+'Enabled',g===group);await aws.getByRole('checkbox',{name,exact:true}).setChecked(g===group);}
  if(group==='alb'){
   for(const [key,label]of [['albNewConnections','Average number of new connections per ALB Value'],['albGbHour','Processed bytes (EC2 Instances and IP addresses as targets) Value'],['albRequests','Average number of requests per second per ALB Enter amount'],['albRules','Average number of rule evaluations per request Enter amount']]){await inputLocal('input-profile--'+key,0);await inputAws(label,0);}
   await inputLocal('input-profile--albConnectionSeconds',1);await inputAws('Average connection duration Value',1);
   const target=f[0].split('--')[1];
   if(target==='albConnectionSeconds'){await inputLocal('input-profile--albNewConnections',1);await inputAws('Average number of new connections per ALB Value',1);await inputLocal(f[0],6000);await inputAws(f[1],6000);}
   else if(['albRequests','albRules'].includes(target)){await inputLocal('input-profile--albRequests',1000);await inputAws('Average number of requests per second per ALB Enter amount',1000);await inputLocal('input-profile--albRules',20);await inputAws('Average number of rule evaluations per request Enter amount',20);}
   else if(target!=='albCount'){await inputLocal(f[0],f[2]);await inputAws(f[1],f[2]);}
  }
  if(group==='nlb'){
   for(const proto of ['tcp','udp','tls']){
    await inputLocal('input-profile--nlb'+proto+'New',0);await inputAws(plans['elastic-load-balancing'].fields.find(x=>x[0]==='input-profile--nlb'+proto+'New')[1],0);
    await inputLocal('input-profile--nlb'+proto+'Seconds',1);await inputAws(plans['elastic-load-balancing'].fields.find(x=>x[0]==='input-profile--nlb'+proto+'Seconds')[1],1);
    await inputLocal('input-profile--nlb'+proto+'Bytes',0);
   }
   const proto=f[0].match(/nlb(tcp|udp|tls)/)?.[1];
   if(proto){const newField=plans['elastic-load-balancing'].fields.find(x=>x[0]==='input-profile--nlb'+proto+'New');
    if(f[0].endsWith('New')){await inputLocal(f[0],f[2]);await inputAws(f[1],f[2]);}
    else{await inputLocal(newField[0],1);await inputAws(newField[1],1);await inputLocal(f[0],f[0].endsWith('Seconds')?6000:1000000);if(f[0].endsWith('Seconds'))await inputAws(f[1],6000);}
   }
   await plans['elastic-load-balancing'].sync();
  }
 }
